begin;
create table if not exists public.service_activity_catalog (
 category text not null,subcategory text not null,area text not null,profession text not null,specialty text not null,service_label text not null,aliases text[] not null default '{}',regulated boolean not null default false,
 primary key(category,subcategory),foreign key(category,subcategory) references public.service_taxonomy(category,subcategory));
alter table public.service_activity_catalog enable row level security;
revoke all on public.service_activity_catalog from anon,authenticated;
grant select on public.service_activity_catalog to authenticated;
create policy activity_catalog_read on public.service_activity_catalog for select to authenticated using(true);
on conflict do nothing;
on conflict(category,subcategory) do update set area=excluded.area,profession=excluded.profession,specialty=excluded.specialty,service_label=excluded.service_label,aliases=excluded.aliases,regulated=excluded.regulated;
create table public.activity_suggestions (
 id uuid primary key default gen_random_uuid(),provider_id uuid not null references public.profiles(id),
 profession text not null check(length(btrim(profession)) between 3 and 100),specialty text not null default '' check(length(specialty)<=120),service text not null check(length(btrim(service)) between 3 and 160),details text not null default '' check(length(details)<=500),
 status text not null default 'pending' check(status in ('pending','accepted','rejected')),admin_note text not null default '' check(length(admin_note)<=500),created_at timestamptz not null default now(),unique(provider_id,profession,specialty,service));
alter table public.activity_suggestions enable row level security;
revoke all on public.activity_suggestions from anon,authenticated;
grant select on public.activity_suggestions to authenticated;
grant insert(provider_id,profession,specialty,service,details) on public.activity_suggestions to authenticated;
grant update(status,admin_note) on public.activity_suggestions to authenticated;
create policy activity_suggestions_read on public.activity_suggestions for select to authenticated using(public.admin_is_current_user() or (provider_id=(select auth.uid()) and exists(select 1 from public.profiles where id=(select auth.uid()) and status='active')));
create policy activity_suggestions_insert on public.activity_suggestions for insert to authenticated with check(provider_id=(select auth.uid()) and status='pending' and admin_note='' and exists(select 1 from public.profiles where id=(select auth.uid()) and status='active' and account_type in ('provider','both')));
create policy activity_suggestions_admin_update on public.activity_suggestions for update to authenticated using(public.admin_is_current_user()) with check(public.admin_is_current_user());
create table public.provider_activity_reviews (
 provider_id uuid not null references public.provider_profiles(id),profession text not null,specialty text not null,
 status text not null check(status in ('approved','rejected')),registration text not null check(length(btrim(registration)) between 3 and 160),evidence_note text not null check(length(btrim(evidence_note)) between 10 and 1000),reviewer uuid not null default auth.uid() references public.profiles(id),reviewed_at timestamptz not null default now(),primary key(provider_id,profession,specialty));
alter table public.provider_activity_reviews enable row level security;
revoke all on public.provider_activity_reviews from anon,authenticated;
grant select on public.provider_activity_reviews to authenticated;

create policy activity_review_read on public.provider_activity_reviews for select to authenticated using(public.admin_is_current_user() or(provider_id=(select auth.uid()) and exists(select 1 from public.profiles where id=(select auth.uid()) and status='active')));

create table public.provider_activity_review_events (
 id uuid primary key default gen_random_uuid(),provider_id uuid not null references public.provider_profiles(id),profession text not null,specialty text not null,status text not null,registration text not null,evidence_note text not null,reviewer uuid not null references public.profiles(id),reviewed_at timestamptz not null default now());
alter table public.provider_activity_review_events enable row level security;
revoke all on public.provider_activity_review_events from anon,authenticated;
grant select on public.provider_activity_review_events to authenticated;
create policy activity_review_events_admin on public.provider_activity_review_events for select to authenticated using(public.admin_is_current_user());
create or replace function public.admin_review_activity(target_provider uuid,target_profession text,target_specialty text,decision text,registration_text text,evidence text)
returns void language plpgsql security definer set search_path='' as $$
begin
 if auth.uid() is null or not public.admin_is_current_user() then raise exception 'Acesso não autorizado' using errcode='42501'; end if;
 if decision not in ('approved','rejected') or decision is null or registration_text is null or length(btrim(registration_text)) not between 3 and 160 or evidence is null or length(btrim(evidence)) not between 10 and 1000 then raise exception 'Confira decisão, registro e evidência' using errcode='23514';end if;
 if not exists(select 1 from public.service_activity_catalog where profession=target_profession and specialty=target_specialty and regulated) then raise exception 'Atividade regulamentada não encontrada' using errcode='23514';end if;
 perform 1 from public.provider_profiles where id=target_provider for update;
 if not found then raise exception 'Prestador não encontrado';end if;
 on conflict(provider_id,profession,specialty) do update set status=excluded.status,registration=excluded.registration,evidence_note=excluded.evidence_note,reviewer=excluded.reviewer,reviewed_at=now();
end;$$;
revoke all on function public.admin_review_activity(uuid,text,text,text,text,text) from public,anon;
grant execute on function public.admin_review_activity(uuid,text,text,text,text,text) to authenticated;
create or replace function public.ajura_activity_allowed(target_provider uuid,target_category text,target_subcategory text)
returns boolean language sql stable security definer set search_path='' as $$
 select exists(select 1 from public.service_activity_catalog c where c.category=target_category and c.subcategory=target_subcategory and(not c.regulated or exists(select 1 from public.provider_activity_reviews v where v.provider_id=target_provider and v.profession=c.profession and v.specialty=c.specialty and v.status='approved')));
$$;
revoke all on function public.ajura_activity_allowed(uuid,text,text) from public,anon;
grant execute on function public.ajura_activity_allowed(uuid,text,text) to authenticated;
create policy provider_services_activity_gate on public.provider_services as restrictive for select to authenticated using(provider_id=(select auth.uid()) or public.admin_is_current_user() or public.ajura_activity_allowed(provider_id,category,subcategory));
create or replace function public.ajura_request_activity_gate() returns trigger language plpgsql security definer set search_path='' as $$
begin
 if not exists(select 1 from public.provider_services s where s.id=new.service_id and public.ajura_activity_allowed(s.provider_id,s.category,s.subcategory)) then raise exception 'Atividade indisponível: aguarda conferência de habilitação' using errcode='42501'; end if;
 return new;
end;$$;
revoke all on function public.ajura_request_activity_gate() from public,anon,authenticated;
create trigger request_activity_gate before insert on public.service_requests for each row execute function public.ajura_request_activity_gate();
commit;
